from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_score = None
    best_versions = None

    initial_constraints = {
        name: [tuple(bounds)] for name, bounds in roots.items()
    }

    def active_dependencies(row):
        for dep in row.get('deps', []):
            feature = dep.get('feature')
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(selected):
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True

            state[name] = 1
            for dep in active_dependencies(selected[name]):
                target = dep['name']
                if target not in selected or not visit(target):
                    return False
            state[name] = 2
            return True

        for name in selected:
            if not visit(name):
                return False
        return True

    def search(selected, constraints):
        nonlocal best_score, best_versions

        for name, ranges in constraints.items():
            if name not in packages:
                return
            if name in selected:
                version = selected[name]['version']
                if version in blocked.get(name, ()):
                    return
                if any(not (low <= version <= high)
                       for low, high in ranges):
                    return
                if name in pins and version != pins[name]:
                    return

        unresolved = [name for name in constraints if name not in selected]
        if not unresolved:
            if not is_acyclic(selected):
                return
            versions = {
                name: row['version'] for name, row in selected.items()
            }
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        name = min(unresolved)
        for row in packages[name]:
            version = row['version']
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if any(not (low <= version <= high)
                   for low, high in constraints[name]):
                continue

            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = {
                key: list(ranges) for key, ranges in constraints.items()
            }
            valid = True

            for dep in active_dependencies(row):
                dep_name = dep['name']
                dep_range = (dep['min'], dep['max'])
                next_constraints.setdefault(dep_name, []).append(dep_range)

                if dep_name not in packages:
                    valid = False
                    break
                if dep_name in next_selected:
                    dep_version = next_selected[dep_name]['version']
                    if (dep_version in blocked.get(dep_name, ()) or
                            not (dep_range[0] <= dep_version <= dep_range[1]) or
                            (dep_name in pins and dep_version != pins[dep_name])):
                        valid = False
                        break

            if valid:
                search(next_selected, next_constraints)

    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}

    return {
        'versions': {
            name: best_versions[name]
            for name in names if name in best_versions
        }
    }
